"""English report content shared by the report and notebook; values read from results."""
import json
from pathlib import Path
import numpy as np,pandas as pd
ROOT=Path(__file__).resolve().parents[1];R=ROOT/'results'
NAMES={'rf_plain':'RF: unweighted','rf_balanced':'RF: balanced','xgb_plain':'XGB: unweighted','xgb_smote':'XGB: SMOTE'}
