def table(headers,rows):return ('table',headers,rows)
def performance(d):
 return table(['Split','Error','ROC-AUC','AP','Precision','Recall','F1'],[[s.title()]+[f'{d[s][k]:.5f}' for k in ['error','auc','average_precision','precision','recall','f1']] for s in ['train','test']])
